await sql.begin(async (tx) => {
	const [product] = await tx`SELECT stock FROM products WHERE id = ${id}`;
	if (product.stock <= 0) throw new Error("sold out");
	await tx`UPDATE products SET stock = ${product.stock - 1} WHERE id = ${id}`;
	await tx`INSERT INTO orders (product_id) VALUES (${id})`;
});

